import React from 'react';
import { ComponentMeta, ComponentStory } from '@storybook/react';
import { Carousel } from '../..';

export default {
  title: 'Data Display/Carousel',
  component: Carousel.Root,
  argTypes: {
    autoRotate: { defaultValue: false },
    autoRotateInterval: { defaultValue: 15_000 },
    size: { defaultValue: 'xl' },
    showArrows: { defaultValue: true },
    swipeable: { defaultValue: true },
  },
  parameters: {
    docs: {
      description: {
        component:
          'How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { Carousel } from "@hexa-ui/components"`<br><br>How to use: `Carousel.Root` and `Carousel.Item` or destructure it `{ Root, Item } = Carousel`<br><br> `Carousel.Item` is subcomponent of `Carousel.Root`',
      },
    },
  },
} as ComponentMeta<typeof Carousel.Root>;

const Template: ComponentStory<typeof Carousel.Root> = (args) => (
  <div style={{ background: '#F6F2FF', padding: '0 64px', width: 630, height: 360 }}>
    <Carousel.Root {...args}>
      {Array.from({ length: 10 }, (_, i) => (
        <Carousel.Item key={i}>
          <img
            src={`https://picsum.photos/1920/1080?random=${i}`}
            alt=""
            style={{ objectFit: 'cover' }}
          />
        </Carousel.Item>
      ))}
    </Carousel.Root>
  </div>
);

export const Default = Template.bind({});

export const moreItemsPerSlide = Template.bind({});
moreItemsPerSlide.args = { size: 'md' };

export const withoutActions = Template.bind({});
withoutActions.args = { showArrows: false, swipeable: false };

export const autoRotate = Template.bind({});
autoRotate.args = { autoRotate: true, autoRotateInterval: 15_000 };
